% demo_2026.m -- from a VCO datasheet to a fixed-filter PLL frequency sweep.
% Generated by GitHub Copilot under Lance Lascari's direction.
% GNU Octave first; MATLAB compatible. Start in a graphical session with a
% command window: demo_2026. No downloads, GUI configurator or local inputs
% are required: the ROS extraction rows ship in the pn/ generation script.
%
% Stage 1 shows the source-noise and tuning-gain plots. After a command-window
% keypress, stage 2 designs a loop at 1725 MHz and analyzes the same filter at
% five frequencies across 1350-2100 MHz. The existing dataset viewer opens.
% All generated data live in pll_synth/_demo_2026/, which is git-ignored.
% No clear/close-all: leave unrelated workspace data and figures alone.

demo_root_directory=fileparts(mfilename('fullpath'));
addpath(fullfile(demo_root_directory,'pn'),fullfile(demo_root_directory,'pll_synth'));

% Set to 0 for unattended runs; retain 1 for the interactive demonstration.
demo_pause_for_key=1;
% 1 allows rerunning this demo's own output files; 0 protects earlier output.
demo_overwrite_results=1;
demo_output_directory=fullfile(demo_root_directory,'pll_synth','_demo_2026');

fprintf('\nRFdude 2026 demonstration: datasheet -> VCO profile -> PLL analysis\n');
fprintf('Source: Mini-Circuits ROS-2100-119+, REV. E, two-page datasheet.\n');
fprintf('The shipped generator transcribes page 2 tables, checked against the PDF and plots.\n');
fprintf('20 nominal carrier/Kvco rows provide noise at 1, 10, 100 and 1000 kHz offsets.\n');
fprintf('A separate table supplies 20 detailed noise offsets at 1725 MHz.\n');
fprintf('The 1725 MHz Kvco is explicitly interpolated; it is not a measured gain.\n');
fprintf('Temperature is not swept. Values are typical characterization, not guarantees.\n');
fprintf('See pn/ros2100_extraction_example.md for evidence and reusable LLM instructions.\n\n');

% Override only output/plot switches; keep the generator's settings and data
% readable and unchanged. This demo never replaces the user's normal ROS MAT.
ros_example_options_s=struct();
ros_example_options_s.bSaveData=1;
ros_example_options_s.bOverwriteData=demo_overwrite_results;
ros_example_options_s.bPlotData=1;
ros_example_options_s.output_filename=fullfile(demo_output_directory,'ROS_2100_119_profile.mat');
aa_generate_ros2100_example;
clear ros_example_options_s;
demo_ros_profile_s=pn_profile_s;
drawnow;

if demo_pause_for_key
    fprintf('Inspect the phase-noise overlay and tuning-sensitivity plots.\n');
    fprintf('Click the command window, then press any key to run the PLL demonstration.\n');
    pause;
end

fprintf('\nStarting the readable PLL example in pll_synth/.\n');
fprintf('Edit aa_demo_ROS_based_synthesizer_runPLL.m to tweak PLL and sweep settings.\n');
aa_demo_ROS_based_synthesizer_runPLL;
